from pocket_coffea.lib.cut_functions import (
    get_HLTsel,
    get_nObj_min,
    get_nBtagMin,
)

# Skim cuts: minimal filters for efficiency
skim_cuts = [
    get_HLTsel(primaryDatasets=["semileptonic"]),
]

# Preselection cuts: physics requirements for 2018 semileptonic ttbar
preselection_cuts = [
    get_HLTsel(primaryDatasets=["semileptonic"]),
    get_nObj_min(N=4, minpt=30, coll="JetGood"),
    get_nBtagMin(N=2, coll="BJetGood"),
]

# Define cut lists for configuration
cuts = {
    "skim": skim_cuts,
    "preselection": preselection_cuts,
}
